  for (ii = 0; ii < _PB_NI; ii += T1)
    for (jj = 0; jj < _PB_NJ; jj += T2)
      for (i2 = ii; i2 < ii + T1 && i2 < _PB_NI; i2++)
        for (j2 = jj; j2 < jj + T2 && j2 < _PB_NJ; j2++)
          {
            E[i2][j2] = SCALAR_VAL(0.0);
            for (k2 = 0; k2 < _PB_NK; ++k2)
              E[i2][j2] += A[i2][k2] * B[k2][j2];
          }
  /* F := C*D */
#pragma omp parallel for private(ii,jj,i2,j2,k2) schedule(static)
  for (ii = 0; ii < _PB_NJ; ii += T1)
    for (jj = 0; jj < _PB_NL; jj += T2)
      for (i2 = ii; i2 < ii + T1 && i2 < _PB_NJ; i2++)
        for (j2 = jj; j2 < jj + T2 && j2 < _PB_NL; j2++)
          {
            F[i2][j2] = SCALAR_VAL(0.0);
            for (k2 = 0; k2 < _PB_NM; ++k2)
              F[i2][j2] += C[i2][k2] * D[k2][j2];
          }
  /* G := E*F */
#pragma omp parallel for private(ii,jj,i2,j2,k2) schedule(static)
  for (ii = 0; ii < _PB_NI; ii += T1)
    for (jj = 0; jj < _PB_NL; jj += T2)
      for (i2 = ii; i2 < ii + T1 && i2 < _PB_NI; i2++)
        for (j2 = jj; j2 < jj + T2 && j2 < _PB_NL; j2++)
          {
            G[i2][j2] = SCALAR_VAL(0.0);
            for (k2 = 0; k2 < _PB_NJ; ++k2)
              G[i2][j2] += E[i2][k2] * F[k2][j2];
          }
#pragma endscop
